<template>
  <div class="screen-display-wrapper">
    <div class="display-container">
      <div v-if="prefix" class="display-prefix">{{ prefix }}</div>
      <div :class="['display-value', bgType === 'bg2' ? 'valueb' : '']">
        {{ displayValue }}
      </div>
      <div v-if="suffix" class="display-suffix">{{ suffix }}</div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'

const props = defineProps({
  value: {
    type: [String, Number],
    default: ''
  },
  prefix: {
    type: String,
    default: ''
  },
  suffix: {
    type: String,
    default: ''
  },
  bgType: {
    type: String,
    default: 'bg1', // 'bg1' | 'bg2'
    validator: (value) => ['bg1', 'bg2'].includes(value)
  },
  precision: {
    type: Number,
    default: undefined
  }
})

const displayValue = computed(() => {
  if (props.value === '' || props.value === null || props.value === undefined) {
    return '--'
  }

  if (props.precision !== undefined && typeof props.value === 'number') {
    return props.value.toFixed(props.precision)
  }

  return props.value
})
</script>

<style scoped>
.screen-display-wrapper {
  width: 100%;
  margin-bottom: 10px;
}

.display-container {
  display: flex;
  align-items: center;
}

.display-value {
  flex: 1;
  height: 40px;
  padding: 0 15px;
  font-size: 16px;
  color: #FFFFFF;

  box-sizing: border-box;
  display: flex;
  align-items: center;
  background-image: url("@/assets/images/valuebg1.png");
  background-position: 0% 0%;
  background-repeat: no-repeat;
  /* background-size: contain; */
  background-position: 95% 65%;
  text-align: center;
  justify-content: right;
}

.display-value.valueb {
  flex: 1;
  height: 40px;
  padding: 0 15px;
  font-size: 16px;
  color: #FFFFFF;

  box-sizing: border-box;
  display: flex;
  align-items: center;
  background-image: url("@/assets/images/valuebg2.png");
  background-position: 0% 0%;
  background-repeat: no-repeat;
  /* background-size: contain; */
  background-position: 95% 65%;
  text-align: center;
}


.display-prefix {
  min-width: 40px;
  font-size: 14px;
  color: rgba(255, 255, 255, 1);
  text-align: center;
  font-family: "SourceHanSansSC 微软雅黑";
  font-weight: bolder;
  flex-shrink: 0;
}

.display-suffix {
  font-family: "SourceHanSansSC 微软雅黑";
  font-weight: bolder;
  min-width: 40px;
  font-size: 14px;
  color: rgba(255, 255, 255, 1);
  text-align: center;
  flex-shrink: 0;
}
</style>
